def test_each_work_mode_says_its_alignment_line_when_the_agent_drifts_from_it(app: App):
    """The builder handing work out twice with no code of its own between, the orchestrator past its lines of its own code since its last handover, and the solo agent sending subagents past its own reads each hear their mode's line once, never in another mode."""
    hook(app, "SessionStart")
    app.console().run(["environment", "overview"], AGENT)
    settings = app.container.get(SettingRows)
    said = lambda kind, **body: json.dumps(hook(app, kind, **body)[1])
    shell = lambda command: said("PreToolUse", tool_name="Bash", tool_input={"command": command})
    handover = lambda: shell("journal worker send 1 'the next job'")

    def edit(name: str, lines: int) -> str:
        change = {"file_path": str(app.config.root / name), "old_string": "x", "new_string": "y"}
        before = said("PreToolUse", tool_name="Edit", tool_input=change)
        hook(app, "PostToolUse", tool_name="Edit", tool_input=change, tool_response={"structuredPatch": [{"oldStart": 1, "newStart": 1, "lines": [f"+line {n}" for n in range(lines)]}]})
        app.runtime().deferred.drain()
        return before

    in_a_row = "times in a row with no code of your own between"
    assert in_a_row not in handover()
    edit("a.py", 1)
    assert in_a_row not in handover(), "a code edit of its own between two handovers starts the count again"
    assert in_a_row in handover(), "two handovers in a row with no code between tell the builder to take the next task itself"
    assert in_a_row not in handover(), "and only once within its repeat span"

    settings.set("workers.mode", "orchestrator", Actor.user(1))
    settings.set("workers.orchestrator_lines", 5, Actor.user(1))
    edit("b.py", 3)
    assert "you are the orchestrator" not in shell("echo checked")
    edit("c.py", 3)
    assert "you are the orchestrator" in shell("echo checked"), "past the limit set on the Settings page the orchestrator is told to hand the work out"
    handover()
    edit("d.py", 3)
    assert "you are the orchestrator" not in shell("echo checked"), "a handover starts its count of lines again"
    assert "you are the builder" not in handover() + handover(), "the builder's line is never said in another mode"

    settings.set("workers.mode", "solo", Actor.user(1))
    settings.set("workers.solo_dispatches", 2, Actor.user(1))
    dispatch = lambda: said("PreToolUse", tool_name="Agent", tool_input={"model": "haiku", "subagent_type": "journal-researcher", "description": "find the footer", "prompt": "find it"})
    assert "you are solo" not in dispatch()
    assert "you are solo" in dispatch() + shell("echo checked"), "subagents past its own reads by the limit tell the solo agent to research itself"


def test_the_orchestrator_is_reminded_of_every_started_plan_and_told_once_of_one_that_stalls(app: App):
    from journal.db.connection import Connection
    from journal.models.plan_state import PlanState
    from journal.repositories.entries import NUDGE, Entries
    from journal.repositories.plans import Plans
    hook(app, "SessionStart")
    console = app.console()
    console.run(["environment", "overview"], AGENT)
    app.container.get(SettingRows).set("workers.mode", "orchestrator", Actor.user(1))
    for title, tasks in (("release", ("write the notes", "tag it")), ("billing", ("the invoice",))):
        console.run(["plan", "create", title, "--brief", f"ship {title}"], USER)
        for task in tasks:
            console.run(["plan", "add", str(app.container.get(Plans).rows()[-1].id), task], USER)
    plans = app.container.get(Plans)
    release, billing = plans.rows()[-2:]
    for plan in (release, billing):
        plans.save(plan.with_(state=PlanState.STARTED), Actor.user(1))
    lines = lambda key: [entry.data["line"] for entry in app.container.get(Entries).all_matching(kind=NUDGE) if entry.data.get("key") == key]

    hook(app, "Stop")
    [status] = lines("workers.started_plans")
    parts = status.removeprefix("started plans: ").split("; ")
    assert parts[0].startswith(f"plan {release.id}, release:") and "0 of 2 tasks done, 2 open with no worker" in parts[0] and parts[1].startswith(f"plan {billing.id}, billing:") and "0 of 1 tasks done, 1 open with no worker" in parts[1], "the orchestrator's status line names both started plans with their counts"
    assert lines("workers.plan_stalled") == [], "no plan is stalled while both moved just now"
    shown = console.run(["plan", "show", "current"], AGENT).text
    assert f"started: plan {release.id}, release" in shown and f"started: plan {billing.id}, billing" in shown, "journal plan show current shows every started plan"

    old = "2020-01-01T00:00:00+00:00"
    connection = app.container.get(Connection)
    connection.execute("UPDATE plans SET updated_at = ? WHERE id = ?", (old, release.id))
    for task_id in plans.plan_task_ids(release):
        connection.execute("UPDATE tasks SET updated_at = ? WHERE id = ?", (old, task_id))
    connection.changed("plans")
    connection.changed("tasks")
    hook(app, "Stop")
    hook(app, "Stop")
    stalled = lines("workers.plan_stalled")
    assert len(stalled) == 1 and stalled[0].startswith(f"plan {release.id} stalled since") and stalled[0].endswith("60 min"), "a plan untouched past the setting is named once as stalled, while the other moves"
    told = lines("workers.started_plans") + stalled
    assert not any(re.search(r"worker \d|journal worker dispatch", line) for line in told), "no line tells which worker to use"


