def test_a_mode_profile_scores_an_ideal_agent_whole_and_names_the_measures_that_drifted():
    from journal.features.workers.support.tool_use_counts import ToolUseCounts
    from journal.features.workers.workers_profiles import WorkersProfiles
    ideal = WorkersProfiles.BUILDER.scored(ToolUseCounts(mode="builder", file_edits=12, handovers=2, research_count=10, subagent_dispatches=1))
    assert (ideal.score, ideal.gaps) == (100, ()), "a builder inside every range scores 100"
    drifted = WorkersProfiles.BUILDER.scored(ToolUseCounts(mode="builder", file_edits=2, handovers=10, research_count=1, subagent_dispatches=6))
    assert drifted.score < 40 and [gap.label for gap in drifted.gaps] == ["your own file edits among your edits and handovers", "your own reads and searches among them and your subagents"], "one far off scores low and names the heavier measure first"
    assert not WorkersProfiles.SOLO.scored(ToolUseCounts(mode="solo", file_edits=2)).is_measured, "too few actions are not scored at all"


def test_a_measure_with_fewer_than_three_events_in_its_window_is_left_out_of_the_score():
    from journal.features.workers.support.tool_use_counts import ToolUseCounts
    from journal.features.workers.workers_profiles import PREPARED_MERGE_SHARE, WAIT_SHARE, WorkersProfiles
    from journal.models.support.wait_use import WaitUse
    two = ToolUseCounts(mode="orchestrator", merges=2, prepared_merges=0, research_count=20)
    three = replace(two, merges=3)
    assert PREPARED_MERGE_SHARE.closeness(two) is None and PREPARED_MERGE_SHARE.closeness(three) == 0.0, "two merges are too few to score, three are scored"
    assert WorkersProfiles.ORCHESTRATOR.scored(two).score == 100 and WorkersProfiles.ORCHESTRATOR.scored(three).score < 100, "a measure left out costs nothing"
    assert WAIT_SHARE.closeness(replace(two, waits=WaitUse(with_wait=1))) == 1.0, "the plans' waits are scored from one task"


def test_an_orchestrator_that_merges_without_reading_proofs_or_running_tests_scores_low_on_that_measure():
    from journal.features.workers.support.tool_use_counts import ToolUseCounts
    from journal.features.workers.workers_profiles import WorkersProfiles
    prepared = WorkersProfiles.ORCHESTRATOR.scored(ToolUseCounts(mode="orchestrator", merges=4, prepared_merges=4, research_count=20))
    unprepared = WorkersProfiles.ORCHESTRATOR.scored(ToolUseCounts(mode="orchestrator", merges=4, prepared_merges=0, research_count=20))
    assert prepared.score == 100 and unprepared.score < prepared.score, "merging with no proof read and no test run first costs score"
    assert unprepared.gaps[0].label == "your merges that followed a read of the proofs and a test run among your merges" and unprepared.gaps[0].percent == 0, "and it is the measure named"


def test_with_the_reviewer_on_the_orchestrator_is_not_measured_on_merge_preparation_and_its_answer_time_runs_from_the_review(app: App):
    from journal.features.reviewing.reviewing_options import ReviewingOptions
    from journal.features.workers.support.tool_use_counts import ToolUseCounts
    from journal.features.workers.workers_conduct import fitness_lines
    from journal.models.reviewer import Reviewer
    from journal.models.worker import Worker
    from journal.engine.support.settings import Settings
    from journal.features.workers.workers_profiles import WorkersProfiles
    unprepared = ToolUseCounts(mode="orchestrator", merges=4, prepared_merges=0, research_count=20)
    assert WorkersProfiles.ORCHESTRATOR.scored(unprepared).score < 100 and WorkersProfiles.reviewed_mode_profile("orchestrator").scored(unprepared).score == 100, "with the reviewer on, merges with no proof read or test run of its own cost the orchestrator nothing"
    assert WorkersProfiles.reviewed_mode_profile("builder") is WorkersProfiles.BUILDER, "the other modes are measured as they were"
    data = type("Workers", (), {"tool_uses": unprepared})()
    values = {WorkersOptions.FITNESS_THRESHOLD.key: 100, ReviewingOptions.REVIEWER.key: False}
    assert fitness_lines("orchestrator", data, Settings(values)), "with the reviewer off a low score is told as today"
    assert not fitness_lines("orchestrator", data, Settings({**values, ReviewingOptions.REVIEWER.key: True})), "and with it on the merge measure no longer lowers it"
    worker = Worker(id=7, environment_id=1, name="Lady Lovelace", dispatcher="s1")
    clocked = worker.delivered(100.0)
    assert clocked.is_unanswered(500.0, 300), "with the reviewer off a clock-out waits on the orchestrator from the clock-out"
    sent = worker.review_requested(100.0, "the parser is done")
    assert not sent.is_unanswered(1000.0, 300), "a worker in review waits on the reviewer, not the orchestrator"
    reviewed = sent.reviewed(900.0, 1, Reviewer(id=9, environment_id=1, session="r-1"), "1 passed")
    assert not reviewed.is_unanswered(1000.0, 300) and reviewed.is_unanswered(1300.0, 300), "its answer time runs from the reviewer's report"
    failed = sent.review_failed(900.0, 1)
    assert not failed.review_pending and type(failed.events[-1]).__name__ == "WorkerReviewFailed" and failed.events[-1].task == 1, "a failed review clears the worker's review and carries the event that tells the orchestrator"
    assert failed.is_unanswered(1300.0, 300), "and from then the work waits on the orchestrator"


def test_every_fitness_score_is_kept_with_its_time_and_gaps_as_a_timeline_point_naming_what_moved_it(app: App):
    from journal.features.workers.support.fitness_point import FitnessPoint
    from journal.http.agents.agent_activity import AgentActivity
    from journal.repositories.agents import Agents
    from journal.repositories.entries import Entries
    hook(app, "SessionStart")
    app.console().run(["environment", "overview"], AGENT)

    def used(tool_name: str, **tool_input):
        hook(app, "PreToolUse", tool_name=tool_name, tool_input=tool_input)
        hook(app, "PostToolUse", tool_name=tool_name, tool_input=tool_input, tool_response="")

    for n in range(30):
        used("Edit", file_path=str(app.config.root / f"t{n}.md"), old_string="x", new_string="y")
        used("Read", file_path=str(app.config.root / f"u{n}.md"))
    for n in range(30):
        used("Bash", command=f"journal worker send 1 'job {n}'")
    app.runtime().deferred.drain()
    points = [FitnessPoint.parsed(entry.data) for entry in app.container.get(Entries).all_matching(kind=FitnessPoint.KIND)]
    moves = [point.moved for point in points]
    assert moves[0] == "not scored yet: too few tool uses in this mode" and "first score in this mode" in moves, moves
    assert any(move.startswith("your own file edits among your edits and handovers: ") and move.endswith("% of the ideal") for move in moves), "a point names the measure that moved the score"
    shape = lambda point: (point.score, point.is_measured, point.gaps, point.parts)
    assert all(points[n].at <= points[n + 1].at and shape(points[n]) != shape(points[n + 1]) for n in range(len(points) - 1)), "a point is kept only when the score, a gap or a measure moved"
    fitness = app.container.get(AgentActivity).page([app.container.get(Agents).current()])[0]["fitness"]
    newest = fitness["timeline"][-1]
    assert (newest["score"], newest["gaps"]) == (fitness["score"], fitness["lines"]) and newest["at"] > 0, "the status bar's row carries the timeline, the newest point the score it shows"


def test_the_fitness_score_waits_for_fifty_tool_uses_in_the_current_work_mode_and_counts_only_those(app: App):
    from journal.features.workers.support.tool_use_counts import ToolUseCounts
    from journal.http.agents.agent_activity import AgentActivity
    from journal.repositories.agents import Agents
    hook(app, "SessionStart")
    app.console().run(["environment", "overview"], AGENT)
    said = lambda kind, **body: hook(app, kind, **body)
    read = lambda n: said("PreToolUse", tool_name="Read", tool_input={"file_path": str(app.config.root / f"m{n}.md")})
    edit = lambda n: said("PreToolUse", tool_name="Edit", tool_input={"file_path": str(app.config.root / f"e{n}.md"), "old_string": "x", "new_string": "y"})
    fitness = lambda: app.container.get(AgentActivity).page([app.container.get(Agents).current()])[0]["fitness"]
    for n in range(30):
        edit(n)
    for n in range(30):
        read(n)
    assert fitness()["mode"] == "builder" and fitness()["is_measured"], "a builder past fifty tool uses is scored"
    app.container.get(SettingRows).set("workers.mode", "orchestrator", Actor.user(1))
    assert not fitness()["is_measured"], "right after the switch there is no score"
    for n in range(49):
        read(100 + n)
    assert not fitness()["is_measured"], "and none through forty-nine tool uses in the new mode"
    read(200)
    assert fitness()["mode"] == "orchestrator" and fitness()["is_measured"], "the fiftieth brings the score"
    counted = ToolUseCounts.counted(app.container.get(Agents).current())
    assert counted.mode_uses == 50 and counted.file_edits == 0, "and it counts only the uses made since the switch, none of the builder's edits"


def test_a_merge_counts_as_checked_after_a_proof_read_and_a_test_run_in_the_workers_worktree_made_after_its_clock_out(app: App, monkeypatch):
    import subprocess
    from journal.features.workers.support.tool_use_counts import ToolUseCounts
    from journal.features.workers.support.worker_branch import WorkerBranch
    from journal.repositories.agents import Agents
    from journal.repositories.workers import Workers
    monkeypatch.setattr(WorkerRunner, "start", lambda self, worker, actor: None)
    console = app.console()
    hook(app, "SessionStart")
    for argv in (["init", "-q", "-b", "main"], ["-c", "user.email=t@example.com", "-c", "user.name=T", "commit", "-q", "--allow-empty", "-m", "start"]):
        subprocess.run(["git", *argv], cwd=app.config.root, capture_output=True, timeout=30)
    for title in ("the parser", "the lexer"):
        console.run(["task", "create", title, "--brief", "b"], AGENT)
    for name, task in (("Lady Lovelace", "1"), ("Ada Byron", "2")):
        out = console.run(["worker", "dispatch", name, "--task", task, "--changes", "the files of its task", "--tests", "Scoped tests", "--profile", "journal-medior", "--worktree", "--no-libraries"], AGENT)
        assert out.code == 0, out.error
    workers, branch = app.container.get(Workers), app.container.get(WorkerBranch)
    for n in (1, 2):
        workers.save(workers.find(n).delivered(timing.time()), Actor.system())
    lovelace, byron = (branch.place(workers.find(n)) for n in (1, 2))
    said = lambda command, folder=app.config.root: hook(app, "PreToolUse", tool_name="Bash", tool_input={"command": command}, cwd=str(folder))
    counted = lambda: (lambda counts: (counts.merges, counts.prepared_merges))(ToolUseCounts.counted(app.container.get(Agents).current()))
    said("journal task show 1")
    said(f"(cd {lovelace} && git rebase -q development && python3 scripts/suite.py)")
    said("journal worker merge 1")
    assert counted() == (1, 1), "a suite run whose line changes into the worker's worktree after its clock-out counts the merge as checked"
    said("journal task show 2")
    said("journal suite")
    said("journal worker merge 2")
    assert counted() == (2, 1), "a test run in the project's own folder does not test the worker's worktree"
    said("journal task show 2")
    said("journal suite", byron)
    said("journal worker merge 2")
    assert counted() == (3, 2), "a run whose working folder is the worktree counts"
    said("journal task show 1")
    said("python3 -m pytest -q", lovelace)
    workers.save(workers.find(1).delivered(timing.time() + 60), Actor.system())
    said("journal worker merge 1")
    assert counted() == (4, 2), "a run made before the worker clocked out is not the test run before its merge"
    said("journal task show 2")
    said(f'(cd "{byron}" && python3 scripts/suite.py)')
    said("journal worker merge 2")
    assert counted() == (5, 3), "a leading cd into the worktree counts with the folder in quotes, as CommandOutputs.ran_within reads it"


def test_a_prompt_the_sessions_scheduler_sent_is_a_scheduled_prompt_out_of_the_load_and_the_unanswered_messages(app: App):
    from datetime import datetime, timedelta, timezone
    from journal.features.workers.support.load_items import LoadItems
    from journal.models.author import Author
    from journal.models.message import Message
    from journal.models.scheduled_job import ScheduledJob
    from journal.repositories.messages import Messages
    from journal.repositories.scheduled_jobs import ScheduledJobs
    hook(app, "SessionStart")
    since = datetime.now(timezone.utc) - timedelta(minutes=1)
    app.container.get(ScheduledJobs).save(ScheduledJob(environment_id=MAIN, session="s1", job_id="0a1b2c3d", cron="*/30 * * * *", prompt="Check the journal is healthy; say nothing when it is", recurring=True), Actor.agent("s1"))
    hook(app, "UserPromptSubmit", prompt="Check the journal is healthy; say nothing when it is")
    hook(app, "UserPromptSubmit", prompt="what is left on the parser?")
    app.runtime().deferred.drain()
    messages = app.container.get(Messages)
    recorded = {message.text: message for message in messages.selected(messages.main_chat().order("id"))}
    scheduled, asked = recorded["Check the journal is healthy; say nothing when it is"], recorded["what is left on the parser?"]
    assert (scheduled.author, scheduled.data.get("kind")) == (Author.SYSTEM, Message.SCHEDULED_PROMPT), "the scheduler's prompt is recorded as a scheduled prompt, not the user's"
    assert asked.author == Author.USER, "a prompt the user typed is still theirs"
    waiting = {item.ref for item in app.container.get(LoadItems).message_items(since)}
    assert f"messages:{scheduled.row_id}" not in waiting and f"messages:{asked.row_id}" in waiting, f"the scheduled prompt is not a message waiting on the orchestrator: {waiting}"
    assert scheduled.row_id not in {message.row_id for message in messages.unanswered()}, "and it is never reminded as unanswered"


def test_a_prompt_repeating_an_earlier_one_word_for_word_at_an_interval_is_scheduled_and_both_are_out_of_the_load_and_the_unanswered(app: App, monkeypatch):
    from datetime import datetime, timedelta, timezone
    import journal.features.messages.listeners.record_typed_prompt as recording
    from journal.features.workers.support.load_items import LoadItems
    from journal.models.author import Author
    from journal.repositories.messages import Messages
    hook(app, "SessionStart")
    since = datetime.now(timezone.utc) - timedelta(minutes=1)
    check = "Run the journal health check: say nothing when it is healthy"
    for prompt in (check, "yes", "yes"):
        hook(app, "UserPromptSubmit", prompt=prompt)
    app.runtime().deferred.drain()

    class HalfAnHourOn(datetime):
        @classmethod
        def now(cls, tz=None):
            return datetime.now(tz) + timedelta(minutes=30)

    monkeypatch.setattr(recording, "datetime", HalfAnHourOn)
    hook(app, "UserPromptSubmit", prompt=check)
    app.runtime().deferred.drain()
    messages = app.container.get(Messages)
    chat = messages.selected(messages.main_chat().order("id"))
    checks, answers = [m for m in chat if m.text == check], [m for m in chat if m.text == "yes"]
    assert len(checks) == 2 and all(m.author == Author.SYSTEM and m.is_scheduled_prompt for m in checks), "the same words half an hour apart are a schedule's: the second arrival and the first are scheduled prompts"
    assert len(answers) == 2 and all(m.author == Author.USER for m in answers), "the same words typed again within a minute are still the user's"
    waiting = {item.ref for item in app.container.get(LoadItems).message_items(since)}
    assert not {f"messages:{m.row_id}" for m in checks} & waiting and {f"messages:{m.row_id}" for m in answers} <= waiting, f"neither arrival waits on the orchestrator: {waiting}"
    assert not {m.row_id for m in checks} & {m.row_id for m in messages.unanswered()}, "and neither is reminded as unanswered"


def test_a_journal_line_typed_as_a_prompt_gets_no_repeat_of_itself(app: App):
    """A prompt that is a journal line already says its words, so its hook adds no line it carries."""
    hook(app, "SessionStart")
    app.console().run(["environment", "overview"], AGENT)
    app.console().run(["message", "send", "look at the footer"], USER)
    from journal.repositories.messages import Messages
    with app.container.get(Scope).environment(1):
        number = app.container.get(Messages).last_user_message().id
    added = hook(app, "UserPromptSubmit", prompt=f"[journal] new message {number}")[1].get("hookSpecificOutput", {}).get("additionalContext", "")
    assert f"new message {number}" not in added, "the line the prompt carries is not added again"


def test_a_message_left_while_the_agent_sits_at_its_prompt_is_typed_to_it(app: App, monkeypatch):
    keystrokes = []
    monkeypatch.setattr(SupervisorLink, "_send", lambda self, environment_id, verb, fields: keystrokes.append({"verb": verb, **fields}["line"]))
    app.console().run(["message", "send", "nobody is here yet"], USER)
    assert keystrokes == [], "no live agent, nothing to type to"
    hook(app, "SessionStart")
    app.console().run(["environment", "overview"], AGENT)
    app.console().run(["message", "send", "are you there?"], USER)
    app.console().run(["message", "send", "hello?"], USER)
    assert keystrokes == ["[journal] new message 2"], "a second line waits while the first is on its way, or it would pile up in the prompt box"
    notified = hook(app, "UserPromptSubmit", prompt="[journal] new message 2")[1]["hookSpecificOutput"]["additionalContext"]
    app.runtime().deferred.drain()
    assert keystrokes == ["[journal] new message 2"], "the first seen back, the agent is at work, so the next waits for its next tool use instead of being typed"
    assert "new messages 2, 3" in notified, "message 1 was shown by the overview, which reads the unread"
    app.console().run(["message", "send", "four"], USER)
    app.console().run(["message", "send", "five"], USER)
    assert "4 messages unread: `journal message unread`" in hook(app, "Stop")[1]["reason"]
    reading = {"tool_name": "Bash", "tool_input": {"command": "journal message unread"}}
    hook(app, "PreToolUse", **reading)
    shown = app.console().run(["message", "unread"], AGENT).text
    after = hook(app, "PostToolUse", **reading, tool_response={"stdout": shown})[1]["hookSpecificOutput"]["additionalContext"]
    assert "reply with [!reply:" not in shown and "are you there?" in shown and "five" in shown, "the read prints the messages alone"
    assert "[!reply:2], [!reply:3], [!reply:4] and [!reply:5] in your turn" in after and after.count("reply with") == 1, "how to answer them comes after the tool use, in its context, in one line"
    assert hook(app, "Stop")[1] == {}, "nothing unread is left"


def test_a_turn_streamed_in_parts_lands_once_whole(app: App):
    from journal.repositories.messages import Messages
    hook(app, "SessionStart")
    hook(app, "MessageDisplay", delta="Good ", message_id="m1", index=0, final=False)
