def test_a_request_filed_for_a_person_is_a_card_in_their_main_chat_on_their_list_and_done_on_the_requesters_when_finished(app: App):
    from types import SimpleNamespace
    from journal.chat.moment_cards import MomentCards
    from journal.events.models.created import Created
    from journal.features.tasks.listeners.request_arrival_card import RequestArrivalCard
    from journal.features.tasks.support.request_cards import RequestCards
    from journal.http.controllers.requests import RequestController
    from journal.models.environment import Environment
    from journal.models.link import Link
    from journal.models.support.ref import Ref
    from journal.models.task import Task
    from journal.models.task_state import TaskState
    from journal.models.user import User
    from journal.repositories.environment_owners import EnvironmentOwners, OWNER
    from journal.repositories.environments import Environments
    from journal.repositories.links import Links
    from journal.repositories.messages import Messages
    from journal.repositories.scope import Scope
    from journal.repositories.tasks import Tasks
    from journal.repositories.users import Users
    from journal.support.row_labels import RowLabels
    environments, links = app.container.get(Environments), app.container.get(Links)
    hub = environments.save(Environment.hub("k-acme", "acme"), Actor.system())
    home = environments.save(Environment(name="bob-main"), Actor.system())
    app.container.get(Users).save(User(name="Ada", email="ada@example.com"), Actor.system())
    bob = app.container.get(Users).save(User(name="Bob", email="bob@example.com"), Actor.system())
    links.save(Link(source=Ref.build(bob), target=Ref.build(home), kind=OWNER), Actor.system())
    with app.container.get(Scope).environment(hub.row_id):
        task = app.container.get(Tasks).save(Task(title="review the plan"), Actor.user(1))
    link = links.save(Link(source=Ref.build(task), target=Ref.build(bob), kind="requested_of"), Actor.user(1))
    listener = RequestArrivalCard(app.container.get(RequestCards), app.container.get(Tasks), app.container.get(RowLabels), SimpleNamespace(user_number=lambda: bob.row_id))
    listener.handle(Created(model=link, actor=Actor.user(1)))
    app.runtime().deferred.drain()
    with app.container.get(Scope).environment(home.row_id):
        cards = [m.text for m in app.container.get(Messages).scoped()]
    assert set(cards) == {f"acme task {task.row_id} is a request for you: review the plan"}, "the card is in the person's main chat, naming the task with its team"
    controller = app.container.get(RequestController)
    assert [row["title"] for row in controller.index(SimpleNamespace(actor=Actor.user(bob.row_id))).body["rows"]] == ["review the plan"], "and the request is on their Requests list"
    with app.container.get(Scope).environment(hub.row_id):
        app.container.get(Tasks).save(app.container.get(Tasks).find(task.row_id).with_(state=TaskState.FINISHED), Actor.user(bob.row_id))
    assert [(row["title"], row["state"]) for row in controller.filed(SimpleNamespace(actor=Actor.user(1))).body["rows"]] == [("review the plan", "done")], "and the requester's page reads it done once the recipient finished it"


def test_a_worker_sent_back_short_gets_the_failures_its_workers_latest_failed_run_printed_cut_at_forty_lines(app: App, tmp_path):
    import time
    from types import SimpleNamespace
    from journal.config import Config
    from journal.features.workers.support.failed_runs import FailedRuns
    from journal.features.workers.support.test_run_folder import TestRunFolder
    from journal.features.shell.support.readers import Readers
    from journal.models.command_output import CommandOutput
    from journal.models.support.worker_moves import WorkerMoves
    from journal.models.worker import Worker
    from journal.repositories.command_outputs import CommandOutputs
    config, outputs = app.container.get(Config), app.container.get(CommandOutputs)
    config.readers.mkdir(parents=True, exist_ok=True)
    reader = config.readers / "worktree-pytest.pattern"
    reader.write_text("# a pytest run's failed tests and assertions\n^FAILED|^E \ncommands: pytest\n")
    readers = app.container.get(Readers)
    readers.default_choice("worktree-pytest")
    worktree = tmp_path / "worker-tree"

    def run(name, lines, ran_in=str(worktree), status=1):
        folder = tmp_path / name
        folder.mkdir()
        (folder / "parts").write_text("R\n")
        (folder / "0.out").write_text("\n".join(lines) + "\n")
        return outputs.save(CommandOutput(chain=name, command="pytest tests/x.py", folder=str(folder), ran_in=ran_in, ended=True, status=status), Actor.system())

    failed = FailedRuns(outputs, readers, SimpleNamespace(folder=lambda worker: worktree), TestRunFolder(readers))
    before = Worker(moves=WorkerMoves((("clocked out", time.time() - 100),)))
    try:
        assert failed.under(before, "the tests fail") == "the tests fail", "a send-back with no run carries only the reason"
        run("short", ["collected 2 items", "FAILED tests/x.py::test_a - assert 1 == 2", "E   assert 1 == 2", "1 failed"])
        assert failed.under(before, "the tests fail").splitlines() == ["the tests fail", "FAILED tests/x.py::test_a - assert 1 == 2", "E   assert 1 == 2"], "the failure rides under the reason as the reader picks it"
        run("elsewhere", ["FAILED tests/y.py::test_b"], ran_in=str(tmp_path / "other-tree"))
        assert "tests/y.py" not in failed.under(before, "the tests fail"), "a run in another folder is not the worker's"
        run("long", [f"FAILED tests/x.py::test_{n}" for n in range(45)])
        lines = failed.under(before, "the tests fail").splitlines()
        assert len(lines) == 1 + 40 + 1 and lines[-1] == "and 5 more lines", "a long failure is cut at forty lines with the count of the rest"
        after = Worker(moves=WorkerMoves((("clocked out", time.time() + 100),)))
        assert failed.under(after, "the tests fail") == "the tests fail", "a run from before the worker's last clock-out is left out"
    finally:
        readers.removed("worktree-pytest")


def test_removing_a_reader_leaves_a_watch_on_its_last_lines_and_the_next_shell_line_answered(app: App, tmp_path):
    from journal.config import Config
    from journal.features.shell.support.output_views import OutputViews
    from journal.models.command_output import CommandOutput
    from journal.repositories.command_outputs import CommandOutputs
    config, outputs = app.container.get(Config), app.container.get(CommandOutputs)
    config.readers.mkdir(parents=True, exist_ok=True)
    (config.readers / "watched-log.pattern").write_text("# the lines with a number\n^[0-9]+\ncommands: make\n")
    folder = tmp_path / "watched"
    folder.mkdir()
    (folder / "parts").write_text("R\n")
    (folder / "0.out").write_text("1 first\nplain second\n3 third\nplain fourth\n")
    output = outputs.save(CommandOutput(chain="watched", command="make all", folder=str(folder), watch_reader="watched-log"), Actor.system())
    views = app.container.get(OutputViews)
    assert views.measured(output).lines == ("1: 1 first", "3: 3 third"), "watched, the output shows the lines its reader picks"
    result = app.console().run(["reader", "remove", "watched-log"], AGENT)
    assert f"outputs {output.row_id} were read through it" in result.text, "removing a reader says which outputs it was reading"
    assert views.measured(output).lines == ("1 first", "plain second", "3 third", "plain fourth"), "after it, the watch shows the last lines"
    assert app.console().run(["output", "list"], AGENT).code == 0, "and the next shell line is answered"


def test_the_orchestrator_reads_the_load_with_the_turns_sets_the_budget_as_the_settings_page_shows_it_and_its_own_suite_never_waits(app: App, tmp_path):
    import threading
    from journal.repositories.environments import Environments
    import time
    from types import SimpleNamespace
    from journal.features.shell.support.readers import Readers
    from journal.features.shell.support.shell_runner import EXIT
    from journal.features.workers.support.test_turns import TestTurns
    from journal.features.workers.workers_options import TEST_BUDGET
    from journal.models.worker import Worker
    from journal.repositories.command_outputs import CommandOutputs
    from journal.repositories.test_turns import TestTurns as TurnRows
    settings = app.container.get(SettingRows)
    settings.set(WorkersOptions.TESTING.key, TEST_BUDGET, Actor.user(1))
    settings.set(WorkersOptions.TEST_COMMAND.key, "pytest -q", Actor.user(1))
    started, gates, results = [], {n: threading.Event() for n in range(101, 106)}, {}

    class Runner:
        def run(self, request, caller, environment):
            number = int(Path(request.cwd).name.removeprefix("wt"))
            started.append(number)
            gates[number].wait(10)
            yield (f"1 failed, 4 passed in 0.2s\n{EXIT} 1\n" if number == 102 else f"5 passed in 0.2s\n{EXIT} 0\n").encode()

    class Crew:
        def find(self, number):
            return Worker(id=number, environment_id=1, name=f"Worker {number}")

        def save(self, row, actor):
            return row

    turns = TestTurns(app.container.get(TurnRows), Runner(), SimpleNamespace(folder=lambda worker: tmp_path / f"wt{worker.id}"), app.container.get(Readers), settings, app.container.get(CommandOutputs), app.container.get(Scope), Crew(), app.container.get(Environments))

    def ask(number):
        with app.container.get(Scope).environment(1):
            results[number] = turns.take(SimpleNamespace(id=number, name=f"Worker {number}", pool_request=0, environment_id=1), f"tests/test_{number}.py", SimpleNamespace())

    def until(test):
        end = time.time() + 10
        while not test() and time.time() < end:
            time.sleep(0.05)
        return test()

    def asking(*numbers):
        threads = [threading.Thread(target=ask, args=(number,)) for number in numbers]
        for thread in threads:
            thread.start()
            time.sleep(0.4)
        return threads

    hour = lambda: tuple(int(count) for count in re.search(r"last hour: (\d+) passed, (\d+) failed", app.console().run(["tests", "load"], AGENT).text).groups())
    before = hour()
    budget = app.console().run(["tests", "budget", "2"], AGENT)
    assert budget.code == 0 and settings.integer(WorkersOptions.TEST_RUNS) == 2, budget.error
    threads = asking(101, 102, 103)
    assert until(lambda: len(started) == 2)
    load = app.console().run(["tests", "load"], AGENT).text
    assert load.startswith("load ") and " cores, " in load and " MB free" in load, load
    assert "going: turn" in load and ", worker 101: tests/test_101.py" in load and ", worker 102: tests/test_102.py" in load, "the turns going, each with its worker and test ids"
    assert "waiting: turn" in load and ", worker 103: tests/test_103.py" in load, "and the turn waiting"
    hook(app, "SessionStart")
    status, _ = hook(app, "PreToolUse", tool_name="Bash", tool_input={"command": "journal suite"}, tool_use_id="suite-1")
    assert status == 200, "the orchestrator's own suite goes at once while a turn waits: the budget gates only workers' turns"
    budget = app.console().run(["tests", "budget", "1", "10"], AGENT)
    assert budget.code == 0 and settings.integer(WorkersOptions.TEST_RUNS) == 1 and settings.integer(WorkersOptions.TESTS_PER_RUN) == 10
    page = got(app, "/journal/settings", {"X-Journal-Env": "main"})[1]["workers"]
    assert (page["test_runs"], page["tests_per_run"]) == (1, 10), "the Settings page shows the budget the command set"
    assert next(row for row in settings.project_rows() if row.key == WorkersOptions.TEST_RUNS.key).updater == AGENT.actor, "written with the caller as its actor"
    gates[101].set()
    gates[102].set()
    assert until(lambda: 101 in results and 102 in results), "the runs already going end as they are"
    assert until(lambda: len(started) == 3) and started[2] == 103, "the turn waiting starts once a run is free under the new budget"
    more = asking(104, 105)
    time.sleep(0.5)
    assert len(started) == 3, "with a budget of 1 the next turns wait for the run going"
    for number in (103, 104, 105):
        gates[number].set()
        assert until(lambda: number in results), "and run in turn"
    assert started == [101, 102, 103, 104, 105]
    for thread in [*threads, *more]:
        thread.join(10)
    assert hour() == (before[0] + 4, before[1] + 1), "with the runs passed and failed in the last hour"
    settings.set(WorkersOptions.TEST_RUNS.key, WorkersOptions.TEST_RUNS.default, Actor.user(1))
    settings.set(WorkersOptions.TESTS_PER_RUN.key, WorkersOptions.TESTS_PER_RUN.default, Actor.user(1))
    settings.set(WorkersOptions.TESTING.key, WorkersOptions.TESTING.default, Actor.user(1))
    settings.set(WorkersOptions.TEST_COMMAND.key, WorkersOptions.TEST_COMMAND.default, Actor.user(1))


def test_merged_work_is_measured_against_its_model_a_sample_is_judged_by_a_general_verifier_and_a_mismatch_is_named_and_scored(app: App, monkeypatch):
    from journal.features.verification.support.verifier_runner import VerifierRunner
    from journal.features.workers.support.tool_use_counts import ToolUseCounts
    from journal.features.workers.workers_profiles import MODEL_FIT_SHARE, WorkersProfiles
    from journal.models.edit import Edit
    from journal.models.link import Link
    from journal.models.support.ref import Ref
    from journal.models.support.worker_moves import WorkerMoves
    from journal.models.worker import Worker
    from journal.repositories.edits import Edits
    from journal.repositories.links import Links
    from journal.repositories.agents import Agents
    from journal.repositories.verifiers import Verifiers
    from journal.repositories.workers import Workers
    monkeypatch.setattr(VerifierRunner, "start", lambda self, verifier, resume="": verifier)
    keystrokes = []
    catch_typed(app, monkeypatch, keystrokes)
    settings, workers, edits = app.container.get(SettingRows), app.container.get(Workers), app.container.get(Edits)
    settings.set(WorkersOptions.MODE.key, "orchestrator", Actor.user(1))
    settings.set(WorkersOptions.MODEL_FIT_SAMPLE.key, 1, Actor.user(1))
    hook(app, "SessionStart")

    # a worker's job on `model`, `lines` lines over `files` files, sent back `send_backs` times over `minutes`, merged now
    def merged(name, model, lines, files, send_backs, minutes):
        now = timing.time()
        start = now - minutes * 60
        steps = [("dispatched", start), *[move for back in range(send_backs) for move in (("clocked out", start + 60 + back), ("sent back", start + 90 + back))], ("clocked out", now - 30)]
        with app.container.get(Scope).environment(MAIN):
            worker = workers.save(Worker(environment_id=MAIN, name=name, model=model, session=f"ws-{name}", dispatcher="s1", brief="Change src/parser.py; done when its test passes", moves=WorkerMoves(tuple(steps))), Actor.system())
            for n in range(files):
                edits.save(Edit(environment_id=MAIN, session=f"ws-{name}", path=f"src/part_{n}.py" if n else "tests/test_parser.py", added=lines // files, removed=0, time=start + 120, new_text="x = 1"), Actor.system())
            worker = workers.save(workers.find(worker.row_id).merged(0, now), Actor.system())
        app.runtime().deferred.drain()
        with app.container.get(Scope).environment(MAIN):
            return workers.find(worker.row_id)

    small, large = dict(lines=20, files=1, send_backs=0, minutes=8), dict(lines=900, files=14, send_backs=2, minutes=150)
    fits = {(size, model): merged(f"{size}-{model}", f"claude-{model}-5-5", **work).model_fit for size, work in (("small", small), ("large", large)) for model in ("haiku", "sonnet", "opus")}
    assert fits[("small", "haiku")].called_for.value == "fast" and fits[("large", "opus")].called_for.value == "strongest", "small work calls for the fast model, large for the strongest"
    assert fits[("small", "haiku")].points < fits[("large", "haiku")].points
    assert {key: fit.measured for key, fit in fits.items()} == {("small", "haiku"): "right", ("small", "sonnet"): "too strong", ("small", "opus"): "too strong", ("large", "haiku"): "too weak", ("large", "sonnet"): "too weak", ("large", "opus"): "right"}
    answer = hook(app, "PreToolUse", tool_name="Read", tool_input={"file_path": "a.py"}, tool_use_id="fit-read")[1]
    heard = "\n".join([*keystrokes, str(answer)])
    small_opus = next(w.id for w in workers.global_matching(name="small-opus"))
    assert f"worker {small_opus} ran on claude-opus-5-5 for work a cheaper model would have done" in heard, heard
    assert "ran on claude-haiku-5-5 and was sent back 2 times: work like this needs a stronger model" in heard, heard
    assert "ran on claude-haiku-5-5 for work" not in heard, "a fit is never named"
    agent = app.container.get(Agents).session_agent("s1")
    assert len(agent.model_fits) == 6 and sum(entry.endswith(":right") for entry in agent.model_fits) == 2, agent.model_fits
    counts = ToolUseCounts.counted(agent)
    assert MODEL_FIT_SHARE in WorkersProfiles.ORCHESTRATOR.measures and MODEL_FIT_SHARE.percent(counts) == 33 and MODEL_FIT_SHARE.closeness(counts) < 1.0, "the model fit part of the fitness counts the mismatches against"
    with app.container.get(Scope).environment(MAIN):
        sampled = next(w for w in workers.global_matching(name="large-opus"))
        judging = [link.source for link in app.container.get(Links).all_matching(target=Ref.build(sampled), kind="verifies")]
        verifier = app.container.get(Verifiers).find(judging[-1].id)
    assert verifier.model == "sonnet" and "## The diff" in verifier.brief and "Change src/parser.py" in verifier.brief and "journal verdict model" in verifier.brief, "a merge sampled is judged by a verifier on the general model, never the fast one, handed the brief, the diff and the report"
    answer = app.console().run(["verdict", "model", "too-strong", "one parser module and its test"], Caller.verifier("main", verifier.id, verifier.session, "claude"))
    assert answer.code == 0, answer.error
    with app.container.get(Scope).environment(MAIN):
        judged = workers.find(sampled.row_id).model_fit
    assert (judged.verdict, judged.reason, judged.fit()) == ("too strong", "one parser module and its test", "too strong"), "the verdict is recorded on the worker and counts over the measure"
    assert f"{sampled.row_id}:too strong" in app.container.get(Agents).session_agent("s1").model_fits, "and among its dispatcher's model fits"
    settings.set(WorkersOptions.MODE.key, WorkersOptions.MODE.default, Actor.user(1))
    settings.set(WorkersOptions.MODEL_FIT_SAMPLE.key, WorkersOptions.MODEL_FIT_SAMPLE.default, Actor.user(1))


def test_a_workers_turn_to_run_tests_starts_when_fewer_runs_go_than_the_budget_else_waits_in_order_and_one_past_the_waiting_cap_is_refused(app: App, tmp_path):
    import threading
    import time
    from types import SimpleNamespace
    from journal.features.shell.support.readers import Readers
    from journal.features.workers.support.test_turns import TestTurns
    from journal.models.worker import Worker
    from journal.repositories.command_outputs import CommandOutputs
    from journal.repositories.environments import Environments
    from journal.repositories.test_turns import TestTurns as TurnRows
    from journal.repositories.workers import Workers
    from journal.support.rejection import Rejection
    settings = app.container.get(SettingRows)
    started, gates, results, refused = [], {n: threading.Event() for n in (1, 2, 3)}, {}, []

    class Runner:
        def run(self, request, caller, environment):
            started.append(request.cwd)
            number = int(Path(request.cwd).name.removeprefix("wt"))
            gates[number].wait(10)
            yield f"FAILED tests/test_{number}.py::test_it\n".encode()

    class Crew:
        def __init__(self):
            self.kept = []

        def find(self, number):
            return Worker(id=number, environment_id=1, name=f"Worker {number}")

        def save(self, row, actor):
            self.kept.append(row.id)
            return row

    crew = Crew()
    turns = TestTurns(app.container.get(TurnRows), Runner(), SimpleNamespace(folder=lambda worker: tmp_path / f"wt{worker.id}"), app.container.get(Readers), settings, app.container.get(CommandOutputs), app.container.get(Scope), crew, app.container.get(Environments))

    def worker(number):
        return SimpleNamespace(id=number, name=f"Worker {number}", pool_request=0, environment_id=1)

    def ask(number):
        with app.container.get(Scope).environment(1):
            try:
                results[number] = turns.take(worker(number), f"tests/test_{number}.py", SimpleNamespace())
            except Rejection as refusal:
                refused.append(str(refusal))

    def until(test):
        end = time.time() + 10
        while not test() and time.time() < end:
            time.sleep(0.05)
        return test()

    def asking(*numbers):
        threads = [threading.Thread(target=ask, args=(number,)) for number in numbers]
        for thread in threads:
            thread.start()
            time.sleep(0.4)
        return threads

    settings.set(WorkersOptions.TEST_COMMAND.key, "pytest -q", Actor.user(1))
    settings.set(WorkersOptions.TEST_RUNS.key, 2, Actor.user(1))
    threads = asking(1, 2, 3)
    assert until(lambda: len(started) == 2) and started == [str(tmp_path / "wt1"), str(tmp_path / "wt2")], "a budget of 2 starts two runs, each in its own worker's worktree"
    time.sleep(0.5)
    assert len(started) == 2, "and the third waits"
    gates[1].set()
    assert until(lambda: len(started) == 3) and started[2] == str(tmp_path / "wt3"), "until one ends, when it starts"
    gates[2].set()
    gates[3].set()
    for thread in threads:
        thread.join(10)
    assert all(f"tests/test_{n}.py::test_it" in results[n] for n in (1, 2, 3)), "each worker is handed its own result"
    assert sorted(crew.kept) == [1, 2, 3], "and how each run ended is kept on its worker"

    started.clear(), results.clear()
    gates.update({n: threading.Event() for n in (1, 2, 3)})
    settings.set(WorkersOptions.TEST_RUNS.key, 1, Actor.user(1))
    threads = asking(1, 2, 3)
    assert until(lambda: len(started) == 1)
    time.sleep(0.5)
    assert len(started) == 1, "a budget of 1 runs one at a time"
    for number in (1, 2, 3):
        gates[number].set()
        assert until(lambda: number in results), "and in turn"
    assert [Path(cwd).name for cwd in started] == ["wt1", "wt2", "wt3"]

    started.clear(), results.clear()
    gates.update({n: threading.Event() for n in (1, 2, 3)})
    settings.set(WorkersOptions.TEST_WAITING.key, "1", Actor.user(1))
    threads = asking(1, 2, 3)
    assert refused == ["1 turns already wait for a test run: ask again once one has run"], "a turn past the waiting cap is refused with one line"
    for number in (1, 2):
        gates[number].set()
    for thread in threads:
        thread.join(10)


def test_a_test_run_stops_at_its_time_limit_a_worker_that_ends_takes_out_its_turns_and_waiting_turns_start_again_after_a_restart(app: App, tmp_path, monkeypatch):
    import threading
    import time
    from types import SimpleNamespace
    from journal.features.shell.support.output_files import OutputFiles
    from journal.features.shell.support.readers import Readers
    from journal.features.workers.support.test_turns import TestTurns
    from journal.models.command_output import CommandOutput
    from journal.models.worker import Worker
    from journal.repositories.command_outputs import CommandOutputs
    from journal.repositories.environments import Environments
    from journal.repositories.test_turns import TestTurns as TurnRows
    from journal.repositories.workers import Workers
    settings, outputs, scope = app.container.get(SettingRows), app.container.get(CommandOutputs), app.container.get(Scope)
    started, gates, results, stops = [], {}, {}, []

    class Crew:
        def find(self, number):
            return Worker(id=number, environment_id=1, name=f"Worker {number}")

        def save(self, row, actor):
            return row

    crew = Crew()
    monkeypatch.setattr(OutputFiles, "stop", lambda self, reason: (stops.append((self.folder.name, reason)), gates[int(self.folder.name.removeprefix("run"))].set()))

    class Runner:
        def run(self, request, caller, environment):
            number = int(Path(request.cwd).name.removeprefix("wt"))
            started.append(number)
            with scope.environment(1):
                row = outputs.save(CommandOutput(chain=f"run{number}", command=request.line, folder=str(tmp_path / f"run{number}"), ran_in=request.cwd), Actor.system())
                gates.setdefault(number, threading.Event()).wait(10)
                outputs.save(outputs.find(row.row_id).with_(ended=True), Actor.system())
            yield f"FAILED tests/test_{number}.py::test_it\n".encode()

    def fresh():
        started.clear(), gates.clear(), results.clear(), stops.clear()
        gates.update({n: threading.Event() for n in range(1, 5)})
        return TestTurns(app.container.get(TurnRows), Runner(), SimpleNamespace(folder=lambda worker: tmp_path / f"wt{worker.id}"), app.container.get(Readers), settings, outputs, scope, crew, app.container.get(Environments))

    def worker(number):
        return SimpleNamespace(id=number, name=f"Worker {number}", pool_request=0, environment_id=1)

    def ask(turns, number):
        with scope.environment(1):
            results[number] = turns.take(worker(number), f"tests/test_{number}.py", SimpleNamespace())

    def asking(turns, *numbers):
        threads = [threading.Thread(target=ask, args=(turns, number)) for number in numbers]
        for thread in threads:
            thread.start()
            time.sleep(0.4)
        return threads

    def until(test):
        end = time.time() + 10
        while not test() and time.time() < end:
            time.sleep(0.05)
        return test()

    settings.set(WorkersOptions.TEST_COMMAND.key, "pytest -q", Actor.user(1))
    settings.set(WorkersOptions.TEST_RUNS.key, 1, Actor.user(1))
    settings.set(WorkersOptions.TEST_RUN_MINUTES.key, 0.01, Actor.user(1))
    turns = fresh()
    threads = asking(turns, 1, 2)
    assert until(lambda: 1 in results) and "timed out" in results[1] and [name for name, _ in stops] == ["run1"], "a run past the time limit is stopped and reported to its worker as timed out"
    assert until(lambda: started == [1, 2]), "and its place goes to the next waiting turn"
    gates[2].set()
    for thread in threads:
        thread.join(10)

    settings.set(WorkersOptions.TEST_RUN_MINUTES.key, 10, Actor.user(1))
    turns = fresh()
    first = asking(turns, 1)
    follow = asking(turns, 2)
    assert started == [1]
    turns.release(1)
    assert until(lambda: started == [1, 2]) and [name for name, _ in stops] == ["run1"], "a worker that ends has its running run stopped, its waiting turn gone, and the next turn starts"
    gates[2].set()
    for thread in follow:
        thread.join(10)

    turns = fresh()
    with scope.environment(1):
        for number in (1, 2, 3):
            turns.asked(SimpleNamespace(id=number, name=f"Worker {number}", pool_request=0, environment_id=1), "t", "pytest -q t", str(tmp_path / f"wt{number}"))
    resumed = turns.resume()
    for number in (1, 2, 3):
        assert until(lambda: len(started) == number) and started == list(range(1, number + 1)), "after a restart the waiting turns run in order, one at a time"
        gates[number].set()
    for thread in resumed:
        thread.join(10)


def test_a_turn_runs_the_projects_test_command_is_refused_without_one_and_a_worker_holds_one_turn_and_a_worktree_one_run(app: App, tmp_path):
    import threading
    import time
    from types import SimpleNamespace
    from journal.features.shell.support.readers import Readers
    from journal.features.workers.support.test_turns import TestTurns
    from journal.models.worker import Worker
    from journal.repositories.command_outputs import CommandOutputs
    from journal.repositories.environments import Environments
    from journal.repositories.test_turns import TestTurns as TurnRows
    from journal.support.rejection import Rejection
    settings, scope = app.container.get(SettingRows), app.container.get(Scope)
    lines, gates, saved = [], {}, []

    class Crew:
        def find(self, number):
            return Worker(id=number, environment_id=1, name=f"Worker {number}")

        def save(self, row, actor):
            saved.append(row)
            return row

    class Runner:
        def run(self, request, caller, environment):
            lines.append((request.line, Path(request.cwd).name))
            gates.setdefault(request.line, threading.Event()).wait(10)
            if "nope" in request.line:
                yield b"ERROR: file or directory not found: nope.py\n__journal_exit 4\n"
            else:
                yield b"1 passed\n__journal_exit 0\n"

    folders = {"a": tmp_path / "a", "b": tmp_path / "b", "bare": tmp_path / "bare"}
    for name in ("a", "b"):
        (folders[name] / "tests").mkdir(parents=True)
    folders["bare"].mkdir()
    where = {1: "a", 2: "a", 3: "b", 4: "bare"}
    turns = TestTurns(app.container.get(TurnRows), Runner(), SimpleNamespace(folder=lambda worker: folders[where[worker.id]]), app.container.get(Readers), settings, app.container.get(CommandOutputs), scope, Crew(), app.container.get(Environments))
    settings.set(WorkersOptions.TEST_RUNS.key, 3, Actor.user(1))
    results = {}

    def ask(number, ids):
        with scope.environment(1):
            try:
                results[number] = turns.take(SimpleNamespace(id=number, name=f"Worker {number}", pool_request=0, environment_id=1), ids, SimpleNamespace())
            except Rejection as refusal:
                results[number] = f"refused: {refusal}"

    def until(test):
        end = time.time() + 10
        while not test() and time.time() < end:
            time.sleep(0.05)
        return test()

    ask(4, "tests/x.py")
    assert results[4] == f"refused: this project has no test command: set {WorkersOptions.TEST_COMMAND.key}", "a project with no test command refuses a turn in one line naming the setting"
    settings.set(WorkersOptions.TEST_COMMAND.key, "make check", Actor.user(1))
    gates["make check tests/x.py"] = threading.Event()
    gates["make check tests/x.py"].set()
    ask(3, "tests/x.py")
    assert lines == [("make check tests/x.py", "b")], "the configured command runs with the test ids"
    settings.set(WorkersOptions.TEST_COMMAND.key, "", Actor.user(1))
    gates["pytest -q nope.py"] = threading.Event()
    gates["pytest -q nope.py"].set()
    ask(3, "nope.py")
    assert lines[-1] == ("pytest -q nope.py", "b") and "file or directory not found" in results[3], "with none set, pytest runs where there is a tests folder, and a missing test comes back as the runner's not found result"
    assert saved and saved[-1].failing_runs == 1, "as a failed run, counted toward the failing runs"
    first = threading.Thread(target=ask, args=(1, "tests/one.py"))
    first.start()
    assert until(lambda: lines[-1][0] == "pytest -q tests/one.py"), "a turn started"
    second = threading.Thread(target=ask, args=(2, "tests/two.py"))
    second.start()
    time.sleep(0.6)
    assert lines[-1][0] == "pytest -q tests/one.py", "two workers in one worktree go one after another, whatever the budget"
    again = threading.Thread(target=ask, args=(1, "tests/again.py"))
    again.start()
    again.join(10)
    assert results[1].startswith("refused: worker 1") and "has a turn open already" in results[1], "a worker's second turn is refused while its first is open"
    gates.setdefault("pytest -q tests/one.py", threading.Event()).set()
    assert until(lambda: lines[-1][0] == "pytest -q tests/two.py"), "and the second starts once the first ends"
    gates.setdefault("pytest -q tests/two.py", threading.Event()).set()
    first.join(10)
    second.join(10)


def test_a_turn_of_more_ids_than_tests_per_run_runs_in_batches_each_in_the_budget_and_comes_back_as_one_result_with_the_totals(app: App, tmp_path):
    import threading
    from types import SimpleNamespace
    from journal.features.shell.support.readers import Readers
    from journal.features.workers.support.test_turns import TestTurns
    from journal.models.worker import Worker
    from journal.repositories.command_outputs import CommandOutputs
    from journal.repositories.environments import Environments
    from journal.repositories.test_turns import TestTurns as TurnRows
    settings, scope = app.container.get(SettingRows), app.container.get(Scope)
    lines, going, most = [], [], [0]

    class Crew:
        def find(self, number):
            return Worker(id=number, environment_id=1, name=f"Worker {number}")

        def save(self, row, actor):
            return row

    class Runner:
        def run(self, request, caller, environment):
            lines.append(request.line)
            going.append(1)
            most[0] = max(most[0], len(going))
            outcome = b"FAILED tests/a.py::t - assert 1 == 2\n1 failed, 1 passed in 0.1s\n__journal_exit 1\n" if len(lines) == 1 else b"%d passed in 0.1s\n__journal_exit 0\n" % (2 if len(lines) == 2 else 1)
            going.pop()
            yield outcome

    turns = TestTurns(app.container.get(TurnRows), Runner(), SimpleNamespace(folder=lambda worker: tmp_path), app.container.get(Readers), settings, app.container.get(CommandOutputs), scope, Crew(), app.container.get(Environments))
    settings.set(WorkersOptions.TEST_COMMAND.key, "pytest -q", Actor.user(1))
    settings.set(WorkersOptions.TESTS_PER_RUN.key, 2, Actor.user(1))
    settings.set(WorkersOptions.TEST_RUNS.key, 1, Actor.user(1))
    with scope.environment(1):
        result = turns.take(SimpleNamespace(id=1, name="Worker 1", pool_request=0, environment_id=1), "a.py b.py c.py d.py e.py", SimpleNamespace())
    assert lines == ["pytest -q a.py b.py", "pytest -q c.py d.py", "pytest -q e.py"], "five ids with two to a run are three runs, the ids kept whole"
    assert most[0] == 1, "each run takes its own place in the budget"
    assert "FAILED tests/a.py::t" in result and "2 passed" in result, "a failing first batch does not stop the others, and the result holds each batch's lines"
    assert result.splitlines()[-1] == "3 runs: 4 passed, 1 failed", "with one line of totals"


def test_a_finished_plan_says_what_follows_and_a_plan_in_review_names_the_reports_not_read_yet(app: App):
    from datetime import datetime, timezone
    from journal.features.plans.plans_nudges import PlansNudges
    from journal.features.plans.support.review_rounds import ReviewRounds
    from journal.models.link import Link
    from journal.models.plan import Plan
    from journal.models.report import Report
    from journal.models.support.ref import Ref
    from journal.repositories.links import Links
    from journal.repositories.messages import Messages
    from journal.repositories.plans import Plans
    from journal.repositories.reports import Reports
    done = PlansNudges.PLAN_FINISHED.create(n=7).rendered()
    assert "plan 7 done" in done and "final suite" in done and "merging to main and releasing wait for the user's word" in done, done
    assert PlansNudges.review_countdown(3, 2, (12, 14)).rendered().startswith("plan 3 readied due: 2; unread: reports 12, 14")
    assert PlansNudges.review_countdown(3, 0, (12,)).rendered().startswith("plan 3 readied due: 0; unread: reports 12")
    assert PlansNudges.review_countdown(3, 2).rendered() == "plan 3 readied due: 2", "no unread report, nothing named"
    plan = app.container.get(Plans).save(Plan(title="the hub"), Actor.user(1))
    rounds, reports, links = app.container.get(ReviewRounds), app.container.get(Reports), app.container.get(Links)
    rounds.begin(plan, Actor.user(1))
    unread, read = (reports.save(Report(title=title), Actor.agent("s1")) for title in ("reviewer one", "researcher two"))
    for report in (unread, read):
        links.save(Link(source=Ref.build(report), target=Ref.build(plan), kind=Messages.SUBJECT_LINK), Actor.agent("s1"))
    reports.save(read.read(datetime.now(timezone.utc)), Actor.user(1))
    assert [report.row_id for report in rounds.unread(plan)] == [unread.row_id], "of the reports filed about the plan in its review only the unread one is named"


def test_checking_a_point_whose_proof_names_a_test_warns_when_no_run_of_it_is_recorded_since_the_clock_out(app: App, tmp_path):
    import time
    from types import SimpleNamespace
    from journal.features.shell.support.readers import Readers
    from journal.features.workers.support.failed_runs import FailedRuns
    from journal.features.workers.support.test_run_folder import TestRunFolder
    from journal.models.command_output import CommandOutput
    from journal.models.support.worker_moves import WorkerMoves
    from journal.models.worker import Worker
    from journal.repositories.command_outputs import CommandOutputs
    outputs = app.container.get(CommandOutputs)
    runs = FailedRuns(outputs, app.container.get(Readers), SimpleNamespace(folder=lambda worker: tmp_path / "tree"), app.container.get(TestRunFolder))
    worker = Worker(id=4, moves=WorkerMoves((("clocked out", time.time() - 100),)))
    proof = "parser.py:12, and the test tests/test_parser.py::test_reads passes"
    assert runs.unrun(worker, proof) == "no run of tests/test_parser.py::test_reads is recorded since worker 4 clocked out: run it before you trust the point", "no run: one line naming the test"
    assert runs.unrun(worker, "parser.py:12 reads the grammar") == "", "a proof naming no test has nothing to run"
    outputs.save(CommandOutput(chain="elsewhere", command="pytest -q tests/test_parser.py", folder=str(tmp_path / "o1"), ran_in=str(tmp_path / "other")), Actor.system())
    assert runs.unrun(worker, proof), "a run in another folder is not a run of this worker's work"
    outputs.save(CommandOutput(chain="ran", command="pytest -q tests/test_parser.py", folder=str(tmp_path / "o2"), ran_in=str(tmp_path / "tree")), Actor.system())
    assert runs.unrun(worker, proof) == "", "with a run of the test's file in the worker's worktree no warning"
    later = Worker(id=4, moves=WorkerMoves((("clocked out", time.time() + 100),)))
    assert runs.unrun(later, proof), "a run from before the clock-out does not count"
    lexer = "lexer.py:4, and the test tests/test_lexer.py::test_tokens passes"
    outputs.save(CommandOutput(chain="narrow", command=f'cd "{tmp_path / "tree"}" && python3 scripts/suite.py -k parser', folder=str(tmp_path / "o3")), Actor.system())
    assert runs.unrun(worker, lexer), "a run narrowed to other tests does not run this one"
    outputs.save(CommandOutput(chain="suite", command=f'cd "{tmp_path / "tree"}" && python3 scripts/suite.py', folder=str(tmp_path / "o4")), Actor.system())
    assert runs.unrun(worker, lexer) == "", "a whole suite run started by a leading cd into the worktree runs every test in it"


def test_a_due_start_of_a_check_that_a_run_started_meanwhile_starts_nothing(app: App):
    import time
    from journal.features.checks.support.check_runner import CheckRunner
    from journal.models.check import Check
    from journal.repositories.checks import Checks
    checks, runner = app.container.get(Checks), app.container.get(CheckRunner)
    with app.container.get(Scope).environment(MAIN):
        stale = checks.save(Check(title="slow", command="true", interval=1), Actor.user(1))
        running = checks.save(stale.started(time.time()), Actor.user(1))
        returned = runner.start(stale, Actor.system())
        assert returned.progress.time == running.progress.time == checks.find(stale.row_id).progress.time, "the due tick had read the check before the run began: it starts no second run over the first"


def test_a_task_put_first_in_a_workers_queue_is_the_next_one_sent_and_one_in_another_workers_queue_moves_to_the_head_of_this_one(app: App, monkeypatch):
    import subprocess
    from journal.features.workers.support.worker_runner import WorkerRunner
    from journal.features.workers.support.worker_actions import WorkerActions
    from journal.models.support.ref import Ref
    from journal.models.task_state import TaskState
    from journal.repositories.tasks import Tasks
    from journal.repositories.workers import Workers
    monkeypatch.setattr(WorkerRunner, "start", lambda self, worker, actor: None)
    root = app.config.root
    git = lambda *argv: subprocess.run(["git", *argv], cwd=root, capture_output=True, text=True, timeout=30)
    git("init", "-q", "-b", "main")
    (root / ".gitignore").write_text(".journal/\n")
    git("add", ".gitignore")
    git("-c", "user.email=t@example.com", "-c", "user.name=T", "commit", "-qm", "start")
    console, tasks = app.console(), app.container.get(Tasks)
    hook(app, "SessionStart")
    for title in ("the notes", "the second", "the third", "the fourth", "the other worker's", "its queued one"):
        console.run(["task", "create", title, "--brief", f"{title} is written"], AGENT)
    for name, task in (("Mr. Babbage", "1"), ("Lady Lovelace", "5")):
        console.run(["worker", "dispatch", name, "--task", task, "--changes", "the files of its task", "--tests", "Scoped tests", "--profile", "journal-medior", "--model", "sonnet"], AGENT)
    with app.container.get(Scope).environment(MAIN):
        workers = app.container.get(Workers)
        for number in (1, 2):
            workers.save(workers.find(number).with_(token_hash="h", session=f"w-{number}").ready(1.0), Actor.system())
    queue = lambda number: [task.id for task in tasks.queue(Ref.build(workers.find(number)))]
    assert console.run(["worker", "queue", "1", "2", "3", "4"], AGENT).code == 0
    assert console.run(["worker", "queue", "2", "6"], AGENT).code == 0
    first = console.run(["worker", "queue", "1", "4", "--first"], AGENT)
    assert first.code == 0 and "queue: task 4, task 2, task 3" in first.text, first.error or first.text
    with app.container.get(Scope).environment(MAIN):
        assert queue(1) == [4, 2, 3], "the fourth task is first in the queue"
    moved = console.run(["worker", "queue", "2", "3", "--first"], AGENT)
    assert moved.code == 0 and "queue: task 3, task 6" in moved.text, moved.error or moved.text
    with app.container.get(Scope).environment(MAIN):
        assert queue(2) == [3, 6] and queue(1) == [4, 2], "a task in another worker's queue moves to the head of this one"
        assert tasks.find(3).state == TaskState.DELEGATED
    babbage = Caller.worker("main", 1, "w-1", "claude")
    console.run(["proof", "1", "notes.md:1, written"], babbage)
    console.run(["clock-out", "the notes are written"], babbage)
    console.run(["worker", "check", "1", "1"], AGENT)
    monkeypatch.setattr(WorkerActions, "resumable", lambda self, worker: None)
    merged = console.run(["worker", "merge", "1"], AGENT)
    assert merged.code == 0 and "it went straight on to task 4 from its queue" in merged.text, merged.error or merged.text


def test_a_task_of_a_hub_environment_is_named_with_its_own_team_and_any_other_is_not(app: App):
    from journal.models.environment import Environment
    from journal.models.task import Task
    from journal.repositories.environments import Environments
    from journal.support.row_labels import RowLabels
    environments = app.container.get(Environments)
    acme = environments.save(Environment.hub("k-acme", "acme"), Actor.system())
    beta = environments.save(Environment.hub("k-beta", "beta"), Actor.system())
    labels = app.container.get(RowLabels)
    assert labels.name("task", Task(id=57, environment_id=acme.row_id)) == "acme task 57"
    assert labels.name("task", Task(id=58, environment_id=beta.row_id)) == "beta task 58"
    assert labels.name("task", Task(id=59, environment_id=acme.row_id + beta.row_id + 1000)) == "task 59"
    from journal.models.plan import Plan
    assert labels.name("plan", Plan(id=12, environment_id=beta.row_id)) == "beta plan 12" and labels.name("plan", Plan(id=12, environment_id=acme.row_id)) == "acme plan 12", "the same number in two teams' hubs is told apart by team"


def test_a_server_set_up_in_claude_itself_is_removed_from_the_page_through_claudes_own_command(app: App, monkeypatch):
    import json as j
    from urllib.request import Request as R, urlopen
    from journal.features.mcp.support.health import Health
    from journal.features.mcp.support.health_report import HealthReport
    from journal.features.mcp.support.server_catalogue import ServerCatalogue
    transmitted, removed = [], []
    monkeypatch.setattr(SupervisorLink, "runs", lambda self, environment_id: True)
    monkeypatch.setattr(SupervisorLink, "_send", lambda self, environment_id, verb, fields: transmitted.append({"verb": verb, **fields}))
    monkeypatch.setattr(Health, "probe", lambda self: HealthReport({"blender": ServerCatalogue("blender", "uvx blender-mcp", "connected", "")}))
    monkeypatch.setattr(Health, "remove", lambda self, name, provider: removed.append(name) or name == "blender")
    app.container.get(Health).recheck()
    hook(app, "SessionStart")
    port = app.server().port
    listed = j.load(urlopen(HttpRequest(f"http://127.0.0.1:{port}/journal/mcp", headers={"X-Journal-Env": "main"}), timeout=5))["servers"]
    assert [s["name"] for s in listed] == ["blender"] and listed[0]["managed"] is False
    with urlopen(R(f"http://127.0.0.1:{port}/journal/mcp/blender/remove", data=b"{}", method="POST", headers={"Content-Type": "application/json", "X-Journal-Env": "main"}), timeout=5) as r:
        assert j.loads(r.read()) == {"removed": "blender"}
    assert removed == ["blender"] and transmitted[-1]["verb"] == "restart"
    try:
        urlopen(R(f"http://127.0.0.1:{port}/journal/mcp/nothing/remove", data=b"{}", method="POST", headers={"Content-Type": "application/json", "X-Journal-Env": "main"}), timeout=5)
    except HTTPError as error:
        assert error.code == 404


def test_words_start_a_sequence_from_a_prompt_or_from_the_users_message(app: App, monkeypatch):
    transmitted = []
    monkeypatch.setattr(SupervisorLink, "runs", lambda self, environment_id: True)
    catch_typed(app, monkeypatch, transmitted)
    hook(app, "SessionStart")
    console = app.console()
    console.run(["environment", "overview"], AGENT)
    assert "sequence give me an update" in console.run(["trigger", "list"], AGENT).text, "the update words are a shipped trigger"
    console.run(["sequence", "create", "release", "--steps", "bump | tag"], USER)
    console.run(["trigger", "create", "ship it", "release", "--do", "sequence"], USER)
    body = hook(app, "UserPromptSubmit", prompt="ok, ship it now")[1]
    from journal.repositories.messages import Messages
    with app.container.get(Scope).environment(1):
        fired = [m for m in app.container.get(Messages).rows() if m.text == "Trigger release"]
    assert fired and fired[-1].data["detail"] == "ship it", "the trigger's card names its phrases"
    active = app.container.get(RunTracker)
    assert active.current("s1", 1).title == "release" and "step 1: bump" in hook(app, "Stop")[1].get("reason", ""), "a prompt's words start the sequence and its first step is told at the next stop"
    for _ in range(2):
        console.run(["sequence", "follow"], AGENT)
        console.run(["sequence", "next"], AGENT)
    console.run(["message", "send", "could you give me an update?"], USER)
    app.runtime().deferred.drain()
    from journal.events.agent.ticked import Ticked
    from journal.events.bus import Bus
    app.container.get(Bus).dispatch(Ticked(session="s1", environment_id=1, time=0.0, silence_seconds=60.0))
    app.runtime().deferred.drain()
    said = " ".join(transmitted) + app.container.get(SupervisorLink).pending_lines(1)
    assert active.current("s1", 1).title == "Writing an update" and "See what the update covers" in said, "the user's message starts the update sequence, and the step goes to the agent: typed once it is quiet, or on its next tool use while its held stop keeps it at work"

