def test_a_plan_whose_reviewers_are_back_holds_writes_after_ten_tool_uses_until_it_is_readied(app: App, monkeypatch):
    keystrokes = []
    catch_typed(app, monkeypatch, keystrokes)
    console = app.console()
    console.run(["plan", "create", "p", "--brief", "b"], USER)
    console.run(["plan", "add", "1", "first"], USER)
    console.run(["plan", "phase", "1", "one", "--when", "w"], USER)
    console.run(["plan", "todos", "1", "1", "1"], USER)
    hook(app, "SessionStart")
    console.run(["environment", "overview"], AGENT)
    console.run(["task", "create", "the review", "--start"], AGENT)
    console.run(["plan", "review", "1"], AGENT)
    reviewer = {"subagent_type": "journal-researcher", "description": "Lady Lovelace reads plan 1", "prompt": "read plan 1", "model": "sonnet"}
    hook(app, "PreToolUse", tool_name="Agent", tool_input=reviewer, tool_use_id="t-1")
    app.runtime().deferred.drain()
    told = json.dumps(hook(app, "PostToolUse", tool_name="Agent", tool_input=reviewer, tool_use_id="t-1", tool_response="found two gaps")[1])
    app.runtime().deferred.drain()
    edit = lambda: hook(app, "PreToolUse", tool_name="Edit", tool_input={"file_path": "a.md", "old_string": "a", "new_string": "b"})
    said = told + json.dumps(edit()[1]) + " ".join(keystrokes)
    assert "plan 1's reviewers are all back" in said, "the agent is told to put the review into the plan"
    statuses = [edit()[0] for _ in range(8)]
    held = edit()
    assert statuses == [200] * 8 and held[0] == 409 and "your writes wait until plan 1 is readied" in held[1]["error"], (statuses, held)
    assert console.run(["plan", "show", "1"], AGENT).code == 0, "plan commands still go through"
    assert console.run(["plan", "ready", "1", "--changed", "two gaps filled"], AGENT).code == 0
    app.runtime().deferred.drain()
    assert edit()[0] == 200, "the hold is gone once the plan is ready"


def test_the_developer_profile_names_the_function_a_busy_thread_spends_its_time_in(app: App):
    import threading

    from journal.features.faults.support.thread_sampler import ThreadSampler

    stopping = threading.Event()

    def spinning_for_the_profile():
        while not stopping.is_set():
            sum(range(1000))

    worker = threading.Thread(target=spinning_for_the_profile, name="busy", daemon=True)
    worker.start()
    try:
        sample = ThreadSampler().sampled(0.3)
    finally:
        stopping.set()
        worker.join()
    assert sample.sample_count > 5 and any("spinning_for_the_profile" in place for place in sample.stack_functions), "a thread that works is seen in the function it works in"
    assert not any(place.startswith("MainThread: ") and "sampled" in place for place in sample.busy_functions), "the sampler never counts itself"


def test_a_watched_run_is_told_once_to_drop_its_time_limit_wrapper_from_its_alias_or_its_line(app: App):
    from journal.features.shell.support.shell_runner import ShellRunner
    from journal.features.shell.support.time_limit_wrapper import TimeLimitWrapper
    from journal.models.alias import Alias

    assert TimeLimitWrapper.unwrapped("perl -e 'alarm 590; exec @ARGV' python3 -m pytest -q") == "python3 -m pytest -q"
    assert TimeLimitWrapper.unwrapped("timeout 600 npm test") == "npm test" and TimeLimitWrapper.unwrapped("gtimeout --signal=KILL 10m make") == "make"
    runner = app.container.get(ShellRunner)
    suite = Alias(name="suite", line="perl -e 'alarm 590; exec @ARGV' python3 -m pytest -q")
    told = [line.rendered() for line in runner.alias_wrapper_lines(suite)]
    assert len(told) == 1 and "alias suite" in told[0] and "python3 -m pytest -q" in told[0], "an alias that wraps itself is told to drop the wrapper, with its line without it"
    assert runner.alias_wrapper_lines(suite) == [], "once"
    assert len(runner.line_wrapper_lines("timeout 600 npm test")) == 1 and runner.line_wrapper_lines("timeout 300 npm test") == [], "a plain line likewise, once for its command"
    assert runner.line_wrapper_lines("python3 -m pytest -q") == [] and runner.alias_wrapper_lines(Alias(name="plain", line="make")) == [], "a run without a wrapper is told nothing"


